# Starr, Taggart, Evers & Starr - Biology: The Unity and Diversity of Life (Cengage / NGL).
# Chapter list: 15th edition (the AP Edition Update uses the same chapters), from the publisher's table of contents (cengage.com).
# Summaries cover each chapter's standard topics; they are written for this site, not copied from the book.

def ch(n, title, text, keys):
    return (n, title, [text], keys)

C = [
    ch(1, "Invitation to Biology", "Life is organized from atoms and molecules to cells, tissues, organs, organisms, populations, communities, ecosystems, and the biosphere. All living things need energy and nutrients, maintain homeostasis, and use DNA as hereditary material. Species are named with binomial nomenclature and grouped into three domains: Bacteria, Archaea, and Eukarya. Science uses the scientific method: observations, hypotheses, experiments with control groups, and theories.", ["Levels of organization", "Three domains", "Hypothesis → experiment", "Control vs. experimental group"]),
    ch(2, "Life's Chemical Basis", "Atoms have protons, neutrons, and electrons; isotopes differ in neutrons, and radioisotopes are used as tracers. Atoms form ionic, covalent (polar and nonpolar), and hydrogen bonds. Water's polarity gives it cohesion, high specific heat, and solvent ability. The pH scale measures hydrogen ions; buffers keep pH stable.", ["Covalent, ionic, hydrogen bonds", "Water is polar", "pH: below 7 acidic", "Buffers stabilize pH"]),
    ch(3, "Molecules of Life", "Organic molecules are carbon-based. The four classes are carbohydrates (energy, structure), lipids (fats, phospholipids, steroids), proteins (built from 20 amino acids; shape determines function), and nucleic acids (DNA and RNA built from nucleotides). Dehydration synthesis builds polymers; hydrolysis breaks them. Denaturation destroys protein shape.", ["Four classes of biomolecules", "Proteins from amino acids", "Dehydration synthesis vs. hydrolysis", "Denaturation"]),
    ch(4, "Cell Structure", "Cell theory says all living things are made of cells, which come from other cells. Prokaryotes lack a nucleus; eukaryotes have membrane-bound organelles: nucleus, ribosomes, ER, Golgi, lysosomes, mitochondria, chloroplasts (plants), and the cytoskeleton. The plasma membrane is a phospholipid bilayer (fluid mosaic model).", ["Cell theory", "Prokaryote vs. eukaryote", "Mitochondria make ATP", "Fluid mosaic membrane"]),
    ch(5, "Ground Rules of Metabolism", "Energy can't be created or destroyed (first law of thermodynamics), and entropy increases (second law). ATP is the cell's energy currency. Enzymes are catalysts that lower activation energy; they're affected by temperature, pH, and inhibitors. Membrane transport includes diffusion, osmosis, facilitated diffusion, active transport, endocytosis, and exocytosis.", ["Enzymes lower activation energy", "ATP is energy currency", "Osmosis = water diffusion", "Active transport uses ATP"]),
    ch(6, "Where It Starts—Photosynthesis", "Photosynthesis in chloroplasts converts light energy into chemical energy: 6CO2 + 6H2O → C6H12O6 + 6O2. Light-dependent reactions in the thylakoids make ATP and NADPH and release oxygen from water; the Calvin cycle in the stroma fixes CO2 into sugar. Chlorophyll absorbs red and blue light. C4 and CAM plants adapt to hot, dry climates.", ["Chloroplasts", "Light reactions release O2", "Calvin cycle fixes CO2", "Chlorophyll reflects green"]),
    ch(7, "Releasing Chemical Energy", "Aerobic respiration breaks glucose into CO2 and water, making about 30–32 ATP. Steps: glycolysis (cytoplasm), the Krebs (citric acid) cycle, and the electron transport chain (mitochondria), with oxygen as the final electron acceptor. Without oxygen, fermentation (lactic acid or alcoholic) regenerates NAD+ but makes only 2 ATP.", ["Glycolysis in cytoplasm", "Krebs cycle and ETC in mitochondria", "O2 is final electron acceptor", "Fermentation: 2 ATP"]),
    ch(8, "DNA Structure and Function", "DNA is a double helix of nucleotides (sugar, phosphate, base) with complementary base pairing (A–T, G–C). Its structure was discovered by Watson and Crick using Rosalind Franklin's X-ray data. Replication is semiconservative and uses DNA polymerase, helicase, and ligase. Mutations are changes in DNA sequence.", ["A–T, G–C", "Double helix", "Semiconservative replication", "DNA polymerase"]),
    ch(9, "From DNA to Protein", "Gene expression: transcription (DNA → mRNA in the nucleus by RNA polymerase) and translation (mRNA → protein at ribosomes). Codons are three-base sequences; tRNA brings amino acids using anticodons. The start codon is AUG. Mutations include substitutions and frameshifts (insertions/deletions).", ["Transcription makes mRNA", "Translation at ribosomes", "Codons = 3 bases", "Frameshift mutations"]),
    ch(10, "Control of Gene Expression", "Cells control which genes are expressed through transcription factors, promoters, and epigenetic changes (DNA methylation). In bacteria, operons like the lac operon turn genes on and off. Differential gene expression makes cell types different. Loss of control can cause cancer.", ["Not all genes are expressed", "Lac operon", "Transcription factors", "Epigenetics"]),
    ch(11, "How Cells Reproduce", "The cell cycle includes interphase (G1, S, G2) and mitosis (prophase, metaphase, anaphase, telophase) followed by cytokinesis. Mitosis makes two identical diploid cells. Checkpoints control the cycle; cancer results when control fails. Telomeres shorten with each division.", ["PMAT", "S phase: DNA copied", "Mitosis → identical cells", "Cancer = uncontrolled division"]),
    ch(12, "Meiosis and Sexual Reproduction", "Meiosis produces four genetically different haploid gametes. Crossing over (prophase I) and independent assortment create variation. Fertilization restores the diploid number. Errors such as nondisjunction cause abnormal chromosome numbers.", ["Four haploid cells", "Crossing over", "Independent assortment", "Nondisjunction"]),
    ch(13, "Observing Patterns in Inherited Traits", "Mendel's laws of segregation and independent assortment explain inheritance. Terms: alleles, dominant, recessive, genotype, phenotype, homozygous, heterozygous. Punnett squares predict offspring (monohybrid 3:1, dihybrid 9:3:3:1). Exceptions include incomplete dominance, codominance (ABO blood), multiple alleles, and polygenic traits.", ["Mendel's laws", "Genotype vs. phenotype", "3:1 and 9:3:3:1", "Codominance: ABO blood"]),
    ch(14, "Chromosomes and Human Inheritance", "Humans have 23 pairs of chromosomes (22 autosomes + XX or XY). Pedigrees trace inheritance. Patterns include autosomal dominant (Huntington's), autosomal recessive (cystic fibrosis, sickle cell), and X-linked recessive (hemophilia, color blindness; more common in males). Karyotypes show chromosome changes like trisomy 21.", ["23 pairs", "X-linked more common in males", "Pedigrees", "Karyotype"]),
    ch(15, "Studying and Manipulating Genomes", "Biotechnology tools include restriction enzymes (cut DNA at specific sequences), DNA ligase, plasmids and recombinant DNA, PCR (copies DNA using Taq polymerase), gel electrophoresis (separates DNA by size; small fragments move farther), DNA sequencing, DNA profiling (STRs), CRISPR gene editing, GMOs, and gene therapy.", ["Restriction enzymes cut DNA", "PCR amplifies DNA", "Gel electrophoresis separates by size", "CRISPR edits genes"]),
    ch(16, "Evidence of Evolution", "Evidence includes fossils (dated by radiometric dating), comparative anatomy (homologous structures share ancestry; analogous structures share function), vestigial structures, embryology, and molecular similarities in DNA and proteins. Darwin and Wallace proposed natural selection.", ["Fossils and radiometric dating", "Homologous vs. analogous", "DNA comparisons", "Darwin and Wallace"]),
    ch(17, "Processes of Evolution", "Evolution is change in allele frequencies. Mechanisms: natural selection (directional, stabilizing, disruptive), genetic drift (bottleneck and founder effects), gene flow, and mutation. Hardy-Weinberg equilibrium describes a non-evolving population (p² + 2pq + q² = 1). Speciation requires reproductive isolation.", ["Natural selection types", "Genetic drift", "Hardy-Weinberg", "Reproductive isolation"]),
    ch(18, "Organizing Information About Species", "Taxonomy groups organisms: domain, kingdom, phylum, class, order, family, genus, species. Phylogenetic trees (cladograms) show evolutionary relationships based on shared derived traits.", ["Taxonomic levels", "Binomial nomenclature", "Cladograms", "Shared derived traits"]),
    ch(19, "Life's Origin and Early Evolution", "Early Earth's conditions may have produced organic molecules (Miller-Urey experiment). The RNA world hypothesis proposes RNA came first. Early cells were prokaryotes; photosynthesis added oxygen to the atmosphere. Endosymbiosis explains the origin of mitochondria and chloroplasts.", ["Miller-Urey experiment", "RNA world", "Endosymbiosis", "Oxygen from photosynthesis"]),
    ch(20, "Viruses, Bacteria, and Archaea", "Viruses are nonliving particles of nucleic acid in a protein coat that need host cells (lytic and lysogenic cycles). Bacteria reproduce by binary fission, can share genes through conjugation, and include helpful and pathogenic types. Antibiotic resistance evolves through selection. Archaea often live in extreme environments.", ["Viruses need host cells", "Binary fission", "Antibiotic resistance", "Archaea in extreme habitats"]),
    ch(21, "Protists—The Simplest Eukaryotes", "Protists are mostly single-celled eukaryotes, including algae, amoebas, ciliates, and parasites such as Plasmodium (malaria, spread by mosquitoes).", ["Mostly single-celled eukaryotes", "Algae photosynthesize", "Plasmodium causes malaria", "Diverse group"]),
    ch(22, "The Land Plants", "Plants evolved from green algae. Groups: bryophytes (mosses; nonvascular), seedless vascular plants (ferns), gymnosperms (conifers; naked seeds), and angiosperms (flowering plants with fruits). Plants alternate between gametophyte and sporophyte generations.", ["Mosses nonvascular", "Ferns: seedless vascular", "Gymnosperms: naked seeds", "Angiosperms: flowers and fruit"]),
    ch(23, "Fungi", "Fungi are heterotrophs that absorb nutrients and have cell walls of chitin. They're decomposers and form partnerships (mycorrhizae with roots, lichens with algae). Some cause disease (athlete's foot, yeast infections); others give us antibiotics (penicillin) and yeast for bread.", ["Cell walls of chitin", "Decomposers", "Mycorrhizae and lichens", "Penicillin from fungi"]),
    ch(24, "Animal Evolution—The Invertebrates", "Invertebrates lack backbones and include sponges, cnidarians (jellyfish), flatworms, roundworms, mollusks, annelids, arthropods (the largest group), and echinoderms. Traits used to classify animals include symmetry, tissues, body cavity, and segmentation.", ["Arthropods largest group", "Symmetry", "Body cavities", "Echinoderms"]),
    ch(25, "Animal Evolution—The Vertebrates", "Chordates have a notochord, dorsal nerve cord, pharyngeal slits, and a tail at some stage. Vertebrates include fishes, amphibians, reptiles (including birds), and mammals. The amniotic egg allowed reproduction on land.", ["Chordate traits", "Amniotic egg", "Mammals: hair and milk", "Birds are reptiles"]),
    ch(26, "Human Evolution", "Primates share traits like grasping hands and forward-facing eyes. Hominins include Australopithecus and Homo species; Homo sapiens evolved in Africa. Bipedalism and larger brains are key changes.", ["Primate traits", "Bipedalism", "Homo sapiens from Africa", "Larger brains"]),
    ch(27, "Plant Tissues", "Plant tissues are dermal (protective), ground, and vascular: xylem carries water, phloem carries sugars. Meristems allow growth (apical for length, lateral for width). Monocots and eudicots differ in seed leaves, veins, and flower parts.", ["Xylem: water", "Phloem: sugars", "Meristems", "Monocots vs. eudicots"]),
    ch(28, "Plant Nutrition and Transport", "Roots absorb water and minerals; transpiration pulls water up the xylem (cohesion-tension). Stomata, controlled by guard cells, regulate gas exchange and water loss. Sugars move through phloem from sources to sinks (pressure flow).", ["Transpiration", "Stomata and guard cells", "Cohesion-tension", "Source to sink"]),
    ch(29, "Life Cycles of Flowering Plants", "Flowers contain stamens (male) and carpels (female). Pollination transfers pollen; double fertilization forms the embryo and endosperm. Seeds develop into fruits that aid dispersal. Plants also reproduce asexually.", ["Stamen and carpel", "Double fertilization", "Fruits disperse seeds", "Pollinators"]),
    ch(30, "Communication Strategies in Plants", "Plant hormones control growth: auxin (phototropism), gibberellins (stem growth), cytokinins (cell division), ethylene (fruit ripening), and abscisic acid (dormancy, stomata closing). Plants respond to light, gravity, and touch (tropisms) and use photoperiod to time flowering.", ["Auxin: phototropism", "Ethylene ripens fruit", "Abscisic acid closes stomata", "Tropisms"]),
    ch(31, "Animal Tissues and Organ Systems", "Animal tissues are epithelial, connective, muscle, and nervous. Organs and organ systems work together to maintain homeostasis, mostly through negative feedback.", ["Four tissue types", "Organ systems", "Homeostasis", "Negative feedback"]),
    ch(32, "Neural Control", "Neurons send signals through action potentials (sodium in, potassium out) and communicate at synapses with neurotransmitters. The nervous system has the central (brain and spinal cord) and peripheral (somatic and autonomic) divisions. Reflexes are fast automatic responses.", ["Action potential", "Neurotransmitters at synapses", "CNS vs. PNS", "Reflex arc"]),
    ch(33, "Sensory Perception", "Sensory receptors detect stimuli: mechanoreceptors, thermoreceptors, pain receptors, chemoreceptors, and photoreceptors (rods for dim light, cones for color). The ear handles hearing and balance.", ["Rods vs. cones", "Receptor types", "Hearing and balance", "Brain interprets signals"]),
    ch(34, "Endocrine Control", "Hormones are chemical messengers carried in blood to target cells. The hypothalamus controls the pituitary. Insulin (lowers blood sugar) and glucagon (raises it) come from the pancreas. Other glands: thyroid, adrenal, gonads. Most hormones are regulated by negative feedback.", ["Hypothalamus controls pituitary", "Insulin vs. glucagon", "Target cells", "Negative feedback"]),
    ch(35, "Structural Support and Movement", "The skeleton supports and protects the body and makes blood cells. Muscles contract through the sliding filament model (actin and myosin, powered by ATP and triggered by calcium). Muscle types: skeletal, cardiac, smooth.", ["Sliding filament model", "Actin and myosin", "Calcium triggers contraction", "Three muscle types"]),
    ch(36, "Circulation", "The human heart has four chambers and double circulation (pulmonary and systemic). Arteries carry blood away from the heart; veins return it; capillaries exchange materials. Blood contains plasma, red cells, white cells, and platelets.", ["Four-chamber heart", "Pulmonary and systemic", "Capillaries exchange", "Blood components"]),
    ch(37, "Immunity", "Innate immunity includes skin, inflammation, fever, and phagocytes. Adaptive immunity uses B cells (make antibodies) and T cells (helper and cytotoxic). Memory cells provide lasting protection, which is the basis of vaccines. Disorders include allergies, autoimmunity, and AIDS.", ["Innate vs. adaptive", "B cells make antibodies", "Memory cells → vaccines", "HIV attacks helper T cells"]),
    ch(38, "Respiration", "Gas exchange in the alveoli happens by diffusion. The diaphragm drives breathing. Hemoglobin carries oxygen. Breathing rate is controlled by CO2 levels sensed by the brainstem.", ["Alveoli", "Diaphragm", "Hemoglobin carries O2", "CO2 drives breathing rate"]),
    ch(39, "Digestion and Nutrition", "Digestion breaks food into absorbable molecules: mouth (amylase), stomach (pepsin, acid), small intestine (most digestion and absorption with villi; pancreatic enzymes and bile), and large intestine (water absorption). Good nutrition includes balanced macronutrients and micronutrients.", ["Small intestine absorbs most nutrients", "Villi increase surface area", "Bile emulsifies fat", "Large intestine absorbs water"]),
    ch(40, "Maintaining the Internal Environment", "The kidneys filter blood through nephrons (filtration, reabsorption, secretion), regulating water, salts, and pH. ADH increases water reabsorption. Thermoregulation keeps body temperature stable.", ["Nephrons filter blood", "ADH conserves water", "Kidneys regulate pH", "Thermoregulation"]),
    ch(41, "Animal Reproduction", "Reproduction can be asexual or sexual. Human reproductive systems produce gametes (spermatogenesis, oogenesis) regulated by hormones (FSH, LH, estrogen, progesterone, testosterone). Sexually transmitted infections and contraception are covered.", ["Gametogenesis", "Hormone regulation", "Menstrual cycle", "STIs"]),
    ch(42, "Animal Development", "Development proceeds from zygote to cleavage, blastula, gastrulation (three germ layers: ectoderm, mesoderm, endoderm), and organ formation. Cell differentiation is driven by gene expression. Stem cells can become many cell types.", ["Three germ layers", "Gastrulation", "Differentiation", "Stem cells"]),
    ch(43, "Animal Behavior", "Behavior has genetic and environmental bases. Types include instinct, imprinting, learning (classical and operant conditioning), communication, and social behaviors like altruism.", ["Instinct vs. learned", "Imprinting", "Conditioning", "Altruism"]),
    ch(44, "Population Ecology", "Populations grow exponentially (J-curve) with unlimited resources or logistically (S-curve) up to carrying capacity. Limiting factors are density-dependent or density-independent. Survivorship curves and age structure describe populations.", ["Exponential vs. logistic", "Carrying capacity", "Limiting factors", "Age structure"]),
    ch(45, "Community Ecology", "Species interact through competition, predation, herbivory, parasitism, mutualism, and commensalism. Each species has a niche. Succession (primary and secondary) changes communities over time. Keystone species have large effects.", ["Symbiosis types", "Niche", "Succession", "Keystone species"]),
    ch(46, "Ecosystems", "Energy flows through food chains and webs from producers to consumers; only about 10% transfers to each trophic level. Matter cycles through biogeochemical cycles: water, carbon, nitrogen (bacteria fix nitrogen), and phosphorus.", ["10% energy rule", "Producers and consumers", "Carbon and nitrogen cycles", "Decomposers recycle"]),
    ch(47, "The Biosphere", "Biomes include tropical rainforests, deserts, grasslands, temperate forests, taiga, and tundra, shaped by climate. Aquatic ecosystems include freshwater, estuaries, coral reefs, and the ocean.", ["Biomes shaped by climate", "Tundra and taiga", "Coral reefs", "Estuaries"]),
    ch(48, "Human Impacts on the Biosphere", "Human activities cause habitat loss, pollution, invasive species, overharvesting, and climate change from greenhouse gases. These reduce biodiversity. Conservation and sustainable practices help protect ecosystems.", ["Habitat loss", "Climate change", "Invasive species", "Conservation"]),
]

